// ================================================================
//  TANDARRA ESS v16.4 - CONFIG  (single source of truth)
//  Every tunable parameter for the whole controller lives HERE.
// ================================================================
const CONFIG = {

    // -- Tariff / free window (Contact Energy Good Nights) --------
    freeWindowStartHour:   21,     // free import starts 21:00
    freeWindowStartMinute:  0,     // window always ends at midnight
    activeDays: [1,2,3,4,5],       // Mon-Fri only (Sat/Sun: no free power)
    freeRateNZD:         0.48,     // $/kWh value of free import (0.425 + GST)

    // -- SoC targets (%) ------------------------------------------
    targetSocAt2100:      43,      // base pre-discharge target at 21:00 (forecast lowers it)
    checkpointSocBy2000:  65,      // evening trajectory checkpoint at 20:00
    minSocNormal:         20,      // ESS hard minimum (protect / fault)
    minSocFreeCharge:    100,      // ESS min-SoC written during Phase C grid charge
    daytimeFloorWeekday:  80,      // soft daytime floor Mon-Fri
    daytimeFloorWeekend:  85,      // weekend export floor (before cutoff)

    // -- Weekend behaviour (no free window: protect the battery) --
    weekendUseSunsetCutoff:     true,
    weekendExportCutoffFixed:   15.0,  // fallback hour if sunset unknown
    weekendCutoffOffsetWinter:   3.0,  // hours before sunset at winter solstice (Jun 21)
    weekendCutoffOffsetSummer:   1.0,  // hours before sunset at summer solstice (Dec 21)
    weekendExportMarginPct:        2,  // % above floor before exporting
    weekendFullSoC:              100,  // charge to this after cutoff
    weekendExportFloorAfterFull:  98,  // once full, export surplus down to this

    // -- Grid setpoints (W) - MultiPlus-II 48/10000 (8000W cont. @25C) --
    // -9500 is a request, not a promise: the inverter delivers what it can
    // (loads first, remainder exported). Left at -9500 so export is never
    // the limiting factor.
    setpointNormal:       -150,    // anti-import bias / safe default
    setpointExport:      -9500,    // active export ceiling - matches real 9500W inverter rating
    setpointFreeCharge:   9000,    // Phase C forced grid charge (house + charger)
    maxExportSetpoint:   -9500,    // hard ceiling = inverter continuous limit (confirmed 9500W)
    minExportSetpoint:    -150,

    // -- Daytime export bands (W) ---------------------------------
    // v15: these are RELATIVE to the ACTIVE daytime floor, not absolute
    // SoC. See the EXPORT case in 'ESS Controller' for why.
    exportBandFull:      -9500,    // >= floor +10 points
    exportBandStrong:    -7000,    // floor +5  .. +10
    exportBandGentle:    -5000,    // floor +2  .. +5
    exportBandMinimal:   -2000,    // floor +0  .. +2

    // -- PV full-export override (v15, latching) -------------------
    // While PV is above pvFullExportOnW the array is making surplus
    // faster than the lower bands can shed it, so throttling just
    // parks the excess in the battery and SoC climbs anyway. Force
    // exportBandFull instead. Hysteresis stops setpoint chatter when
    // PV hunts around the threshold on a partly-cloudy day.
    pvFullExportOnW:      8000,    // engage above this
    pvFullExportOffW:     7000,    // release below this

    // -- Big-solar-day export (v16.4) -------------------------------
    // The array can charge the battery at up to ~14.5kW but the inverter
    // only passes ~8kW AC, so on a big solar day the battery fills fast
    // unless it is emptied by exporting hard. The FIRST time PV exceeds
    // pvFullExportOnW (8000W) on a day the forecast says is big
    // (isBigForecastDay: bigDayForecastKwh), the day is LATCHED and we
    // export at pvSurplusExportW in EXPORT/NORMAL/PROTECT, whatever the
    // cloud does to PV in between. It stops when:
    //   - SoC drops under pvSurplusExportMinSoc (re-arms at ResumeSoc), or
    //   - it is too late in the day (sunset - pvBigDayEndBeforeSunsetH,
    //     or pvBigDayEndFallbackHour when sunset is unknown), or
    //   - PV stays under pvBigDayLowPvW for pvBigDayLowPvMin minutes
    //     (a bust day; re-arms if PV climbs back over pvFullExportOnW).
    pvSurplusExportW:         -9000,  // setpoint while the big-day latch is active
    pvSurplusExportMinSoc:       40,  // drop out below this SoC
    pvSurplusExportResumeSoc:    43,  // re-engage only at/above this (stops flapping at 40)
    pvBigDayEndBeforeSunsetH:     3,  // stop this many hours before sunset
    pvBigDayEndFallbackHour:   16.5,  // stop time if sunset unknown (16:30)
    pvBigDayLowPvW:            3000,  // 'PV has collapsed' threshold
    pvBigDayLowPvMin:            45,  // minutes under the threshold before giving up for now

    // -- Control behaviour -----------------------------------------
    exportMarginPct:        5,     // % SoC headroom above trajectory before export
    setpointDeadbandW:    300,     // min change before DBus rewritten
    setpointReassertSec:  300,     // force-rewrite DBus every 5 min regardless
    socStaleTimeoutSec:   120,     // SoC older than this => PROTECT/FAULT
    loopIntervalSec:       60,     // must match the 60s inject
    batteryCapacityKwh: 28.68,     // 2x GSL051280A-B-GBP2
    averageHouseLoadW:   1400,     // fallback if live load unavailable
    overnightEndHour:       8,     // hold -150W until this hour (no solar)
    noExportBeforeHour:     8,     // v16.1: HARD guard in 'ESS Controller' - setpoint never
                                   //   more negative than setpointNormal (-150W) before this
                                   //   hour, whatever mode is requested (FREECHARGE exempt,
                                   //   big-day pre-dawn export exempt down to its 40% target).
                                   //   Keeps the battery for breakfast; sunrise ~06:30, PV
                                   //   is producing usefully by ~08:00.

    // -- Forecast / site -------------------------------------------
    forecastMaxAdjustPct: 25,      // max % forecast can lower the 21:00 target
    forecastMinTarget:    32,      // forecast can never push target below this
    latitude:  -37.2540109,        // 31A Leathem Crescent, Pokeno 2402, NZ
    longitude: 175.0050308,
    systemEfficiency:   0.82,
    solarArrays: [
        { name: 'ENE',    azimuth:  57, tilt: 23, capacityKw: 6.09 },
        { name: 'NNW/NW', azimuth: 326, tilt: 23, capacityKw: 7.83 },
        { name: 'WSW',    azimuth: 237, tilt: 23, capacityKw: 5.52 },
    ],

    // -- Dynamic daytime floor (v16: hourly surplus headroom) ------
    // The MultiPlus can pass at most exportCeilingKw of AC (export + house
    // + pool). Any PV above that, hour by hour, can ONLY go into the
    // battery. The floor is set so the battery has exactly enough room
    // left for the surplus still to come today:
    //     track = 100 - remainingSurplus% - surplusTargetMarginPct
    //     floor = track - surplusFloorBelowTrackPct
    // SoC is steered onto 'track' (early export makes the room); the floor
    // sits well below it so the controller keeps full export while SoC
    // rides the track, and only protects if SoC falls well under it.
    // Both rise through the day as the surplus is used up, so SoC reaches
    // ~100% as the surplus ends instead of at 11am.
    // Loads (pool heat pump etc.) don't change the surplus - they only
    // change the export/load split of the same 9.5kW.
    exportCeilingKw:        8.0,   // v16: REAL AC egress limit (export + all AC loads). Datasheet
                                   //   48/10000: 8000W @25C, 7000W @40C, 6000W @65C continuous.
                                   //   Observed 25-Sep-2026 11:54: 14.6kW PV -> 8.2kW AC out
                                   //   (5.4 load + 2.8 export) + 5.8kW into battery.
    surplusTargetMarginPct:  3,    // end-of-surplus headroom (CCL taper near full)
    surplusFloorBelowTrackPct: 12, // floor = track - this (keeps full export band while on track)
    dynamicFloorMinAbs:      35,   // weekday: never lower than this (free charge 21:00 refills)
    dynamicFloorMinAbsWeekend: 50, // weekend: never lower than this (no free charge)
    weekendDynamicFloor:   true,

    // -- Big forecast day bottom (v16.1) --------------------------------
    // From bigDayFloorFromHour on a big forecast day, the floor's bottom
    // clamp drops so the morning export empties the battery further. Once
    // PV exceeds the inverter ceiling the MPPTs charge the battery
    // directly on the DC bus (e.g. 14kW PV -> ~8kW AC + ~6kW battery), so
    // more empty battery = more PV harvested instead of clipped.
    // The floor still = max(bottom, track - 12) and rises through the day
    // as the surplus is used; from 09:00 the confidence ratio scales the
    // forecast down on a bust day, which lifts the floor automatically.
    bigDayForecastKwh:        60,  // remaining-day forecast at/above this (latched for the day)
    bigDayFloorFromHour:       8,  // lower bottom applies from this hour
    bigDayTiers: [                 // v16.2: bottom SoC by the day's peak forecast (kWh, highest first)
        { kwh: 100, floor: 25 },   //   forecast >= 100kWh -> may drain to 25%
        { kwh:  80, floor: 30 },   //   forecast >=  80kWh -> may drain to 30%
    ],                             //   below the lowest tier: normal dynamicFloorMinAbs applies
    bigDayFloorMinAbs:        25,  // (v16.1, superseded by bigDayTiers - unused)
    bigDayFloorMinAbsWeekend: 40,  // weekend bottom on big days (no free charge that night)

    // -- Big-day pre-dawn export (v16.1) --------------------------------
    // Once PV is up, the battery can only drain at (ceiling - PV), so by
    // 08:00 there's little time left to make room. On a big forecast day,
    // export from the battery BEFORE dawn instead, timed to land at
    // bigDayPreDawnTargetSoc by bigDayPreDawnTargetHour (drain = ceiling
    // minus forecast PV, walked back hour by hour, plus a margin). Holds
    // the target until 08:00 (breakfast reserve), then the big-day floor
    // takes over. Weekday this is last night's free charge sold at 8c.
    bigDayPreDawnExport:      true,
    bigDayPreDawnTargetSoc:     40,   // % to reach by the target hour (breakfast reserve)
    bigDayPreDawnTargetHour:   7.5,   // 07:30
    bigDayPreDawnEarliestHour: 3.0,   // never start before 03:00
    bigDayPreDawnMarginH:     0.25,   // start this much earlier than the calc says   // v16: apply the surplus floor on Sat/Sun too (before cutoff)

    // -- Early export on surplus days (v16) ---------------------------
    // The battery can only be drained as fast as (exportCeilingKw - PV),
    // so once PV reaches the ceiling (~9am in summer) no more room can be
    // made. On surplus days the overnight hold therefore ends early enough
    // to bring SoC down to the floor BEFORE the surplus starts - walked
    // back hour by hour from the forecast profile. Weekday pre-dawn export
    // is energy bought free in last night's 21:00-24:00 window, sold at 8c.
    overnightEndMinHour:        8.0,   // v16.1: early export may not start before 08:00 (breakfast reserve)
    earlyExportMarginH:         0.5,   // start this much earlier than the calc says
};
flow.set('config', CONFIG);

// ---------------- Phase determination ---------------------------
// Weekdays : Phase B (managed day)  00:00-21:00
//            Phase C (free charge)  21:00-24:00
// Weekends : Phase A (self-consume + surplus export, never grid-charge)
// The 00:00-08:00 overnight hold is applied inside the Trajectory Engine.
const now      = new Date();
const totalMin = now.getHours() * 60 + now.getMinutes();
const dow      = now.getDay();
const freeStart = CONFIG.freeWindowStartHour * 60 + CONFIG.freeWindowStartMinute;

const isActiveDay = CONFIG.activeDays.includes(dow);
const isWeekend   = !isActiveDay;

const phase = isActiveDay ? (totalMin >= freeStart ? 'C' : 'B') : 'A';

flow.set('phase', phase);
flow.set('isWeekend', isWeekend);
flow.set('lastTick', now.getTime());

const colour = phase === 'C' ? 'green' : phase === 'B' ? 'blue' : 'grey';
node.status({ fill: colour, shape: 'dot',
    text: 'Phase ' + phase + (isWeekend ? ' (weekend)' : '') + ' | ' + now.toLocaleTimeString() });

msg.phase     = phase;
msg.isWeekend = isWeekend;
return msg;

// Lowers tonight's 21:00 pre-discharge target when good solar is
// forecast for the remaining day (more room to export this evening).
const config        = flow.get('config') || {};
const forecastKwh   = flow.get('forecastKwh');
const forecastValid = flow.get('forecastValid');
const isWeekend     = flow.get('isWeekend') || false;

const baseTarget = config.targetSocAt2100    || 43;
const battCapKwh = config.batteryCapacityKwh || 28.68;
const minTarget  = config.forecastMinTarget  || 32;   // v10 fix: was wrongly minSocNormal
const maxAdjust  = config.forecastMaxAdjustPct || 25;

let dynamicTarget = baseTarget;
let reason = 'base (no forecast)';

if (!isWeekend && forecastValid && forecastKwh !== null && forecastKwh !== undefined) {
    const solarSocPct = (forecastKwh / battCapKwh) * 100;
    const adjustment  = Math.min(solarSocPct * 0.6, maxAdjust);
    dynamicTarget     = Math.max(minTarget, Math.round(baseTarget - adjustment));
    reason = 'forecast ' + forecastKwh.toFixed(1) + 'kWh, adj -' + adjustment.toFixed(1) + '%';
}
if (isWeekend) reason = 'weekend - base target';

flow.set('dynamicTarget', dynamicTarget);

// -- Dynamic daytime floor (v16: hourly surplus headroom) --------
// v15 used  trapped = remainingForecast - 9.5kW * min(hoursLeft, 6).
// By ~10am on a long DST day the remaining forecast drops under 57kWh,
// "trapped" went to 0, the floor snapped back to 80%, SoC was below it,
// the controller went NORMAL (-150W) and ALL PV went into the battery -
// full by 11am. v16 instead sums, hour by hour, only the PV the inverter
// physically can't pass (PV - exportCeilingKw), for the rest of today,
// and keeps exactly that much room in the battery.
const ceilingKw = config.exportCeilingKw || 9.5;
const hourlyPv  = flow.get('forecastHourly') || [];
const confObj   = flow.get('forecastConfidence');
const nowD      = new Date();
const nowHf     = nowD.getHours() + nowD.getMinutes() / 60;
// From 09:00 scale by how the morning actually performed (never scale up)
const confRatio = (nowHf >= 9 && confObj && typeof confObj.ratio === 'number')
    ? Math.min(1, confObj.ratio) : 1;

let surplusKwh = 0;
hourlyPv.forEach(p => {
    if (p.h + 1 <= nowHf) return;                         // hour already over
    const frac = p.h < nowHf ? (p.h + 1 - nowHf) : 1;      // part of current hour left
    surplusKwh += Math.max(0, p.kw * confRatio - ceilingKw) * frac;
});
surplusKwh = Math.round(surplusKwh * 10) / 10;
const surplusPct = (surplusKwh / battCapKwh) * 100;

const useDyn    = forecastValid && hourlyPv.length > 0 && (!isWeekend || config.weekendDynamicFloor);
const baseFloor = isWeekend ? (config.daytimeFloorWeekend || 85) : (config.daytimeFloorWeekday || 80);
// v16.1: big-forecast-day bottom. forecastKwh is the REMAINING day, so it
// shrinks as the day goes on - latch per date from the first reading at or
// above the threshold so the bottom doesn't snap back mid-morning.
const todayStr = nowD.toDateString();
if (forecastValid && (forecastKwh || 0) >= (config.bigDayForecastKwh || 60)) {
    flow.set('bigForecastDate', todayStr);
}
const isBigForecastDay = flow.get('bigForecastDate') === todayStr;
const normalMinAbs = isWeekend ? (config.dynamicFloorMinAbsWeekend || 50) : (config.dynamicFloorMinAbs || 35);
// v16.2: TIERED big-day bottom by forecast size (CONFIG.bigDayTiers).
// forecastKwh is the REMAINING day and shrinks, so latch the day's highest
// reading per date. >=100kWh -> 25%, >=80kWh -> 30%, below that the normal
// dynamic floor minimum applies (weekends: 50%). Tiers apply on weekends too. The confidence ratio still lifts the floor on a bust
// day via headroomFloor, so no manual babysitting.
const tiers = (config.bigDayTiers || [{ kwh: 100, floor: 25 }, { kwh: 80, floor: 30 }])
    .slice().sort((a, b) => b.kwh - a.kwh);
if (flow.get('dayMaxForecastDate') !== todayStr) {
    flow.set('dayMaxForecastDate', todayStr);
    flow.set('dayMaxForecastKwh', 0);
}
if (forecastValid && (forecastKwh || 0) > (flow.get('dayMaxForecastKwh') || 0)) {
    flow.set('dayMaxForecastKwh', forecastKwh);
}
const dayMaxKwh = flow.get('dayMaxForecastKwh') || 0;
const tier      = tiers.find(t => dayMaxKwh >= t.kwh) || null;
const tierFloor = tier ? tier.floor : null;   // same tiers Mon-Sun
const tierActive = tier !== null && nowHf >= (config.bigDayFloorFromHour != null ? config.bigDayFloorFromHour : 8);
const minAbs    = Math.max(config.minSocNormal || 20,
                           tierActive ? Math.min(normalMinAbs, tierFloor) : normalMinAbs);
flow.set('bigDayTierFloor', tierFloor);
flow.set('dayMaxForecastKwh', dayMaxKwh);
flow.set('isBigForecastDay', isBigForecastDay);

// -- v16.1: big-day pre-dawn export start time ------------------------
// Walk back from the target hour, adding (ceiling - PV) per hour (how
// fast the battery can drain), until it covers SoC - target.
let preDawnStartH = null;
{
    const tgtSoc = config.bigDayPreDawnTargetSoc  != null ? config.bigDayPreDawnTargetSoc  : 40;
    const tgtH   = config.bigDayPreDawnTargetHour != null ? config.bigDayPreDawnTargetHour : 7.5;
    const socP   = flow.get('soc');
    if (config.bigDayPreDawnExport !== false && isBigForecastDay && socP != null && nowHf < tgtH) {
        if (socP > tgtSoc) {
            let needKwh = (socP - tgtSoc) / 100 * battCapKwh;
            let h = tgtH;
            while (needKwh > 0 && h > 0) {
                const hr = Math.floor(h - 1e-9);
                const p  = hourlyPv.find(x => x.h === hr);
                const drainKw = Math.max(0.5, ceilingKw - (p ? p.kw : 0));
                const span = h - hr;                       // part of this hour available
                const can  = drainKw * span;
                if (can >= needKwh) { h -= needKwh / drainKw; needKwh = 0; }
                else                { needKwh -= can; h = hr; }
            }
            preDawnStartH = Math.max(config.bigDayPreDawnEarliestHour != null ? config.bigDayPreDawnEarliestHour : 3,
                                     Math.round((h - (config.bigDayPreDawnMarginH || 0.25)) * 100) / 100);
        }
    }
}
flow.set('preDawnExportStartH', preDawnStartH);
flow.set('bigDayFloorActive', tierActive);
const trackSoc  = Math.round(100 - surplusPct - (config.surplusTargetMarginPct || 3));
const headroomFloor = trackSoc - (config.surplusFloorBelowTrackPct || 12);
const dynFloor  = useDyn ? Math.min(baseFloor, Math.max(minAbs, headroomFloor)) : baseFloor;
flow.set('surplusTrackSoc', useDyn ? Math.max(minAbs, trackSoc) : null);

// -- When must export start to reach the floor before the surplus? --
// Walk back from the first surplus hour, adding (ceiling - PV) per hour
// (= how fast the battery can drain), until it covers SoC - floor.
let exportStartH = null;
const socNow = flow.get('soc');
const firstSurplus = hourlyPv.find(p => p.kw * confRatio > ceilingKw);
const drainTo = useDyn ? Math.max(minAbs, trackSoc) : dynFloor;
if (useDyn && firstSurplus && socNow != null && socNow > drainTo) {
    let needKwh = (socNow - drainTo) / 100 * battCapKwh;
    let h = firstSurplus.h;
    while (needKwh > 0 && h > 0) {
        h -= 1;
        const p = hourlyPv.find(x => x.h === h);
        const drainKw = Math.max(0.5, ceilingKw - (p ? p.kw * confRatio : 0));
        needKwh -= drainKw;
        if (needKwh < 0) h += (-needKwh) / drainKw;   // partial hour
    }
    exportStartH = Math.round((h - (config.earlyExportMarginH || 0.5)) * 100) / 100;
}
flow.set('earlyExportStartH', exportStartH);

flow.set('dynamicDaytimeFloor', dynFloor);
flow.set('forecastSurplusKwh', surplusKwh);
flow.set('isSurplusDay', useDyn && surplusKwh > 0.5);

node.status({ fill: 'blue', shape: 'dot',
    text: 'Target: ' + dynamicTarget + '% (' + reason + ') | Floor: ' + dynFloor + '%'
        + (dynFloor < baseFloor ? ' (-' + (baseFloor - dynFloor) + ')' : '')
        + (tierActive ? ' | TIER ' + tier.kwh + 'kWh>=' + minAbs : '')
        + ' | surplus ' + surplusKwh + 'kWh' + (confRatio < 1 ? ' x' + confRatio.toFixed(2) : '') });
return msg;

// Decides the raw intent for this tick:
//   FREECHARGE  - Phase C grid charge (Mon-Fri 21:00-24:00)
//   EXPORT      - daytime export (banded relative to the floor in ESS Controller)
//   DYNAMIC     - evening closed-loop shed toward the 21:00 target
//   NORMAL      - hold -150W (anti-import bias)
//   PROTECT     - SoC missing/stale or at/below required trajectory
const config    = flow.get('config') || {};
const phase     = flow.get('phase') || 'A';
const isWeekend = flow.get('isWeekend') || false;
const soc       = flow.get('soc');
const now       = new Date();

const nowH       = now.getHours() + now.getMinutes() / 60 + now.getSeconds() / 3600;
const freeStartH = config.freeWindowStartHour + config.freeWindowStartMinute / 60;
const activeDays = config.activeDays || [1, 2, 3, 4, 5];

// v10.4 fix: compute + store hoursToFreeWindow FIRST, unconditionally,
// before any early-return branch below. Phase C / PROTECT / the
// overnight hold all used to return before this line ever ran, which
// left the "Hours to Free Window" sensor stuck on Unknown whenever the
// controller was in any of those states (e.g. every night 00:00-08:00).
// Also now correctly counts down across weekend boundaries instead of
// just clamping to 0 once today's 21:00 has passed.
let hoursLeft;
if (!isWeekend && nowH < freeStartH) {
    hoursLeft = freeStartH - nowH;
} else {
    let daysAhead = 1;
    while (daysAhead <= 7 && !activeDays.includes((now.getDay() + daysAhead) % 7)) {
        daysAhead++;
    }
    hoursLeft = (daysAhead * 24) - nowH + freeStartH;
}
flow.set('hoursToFreeWindow', hoursLeft);

// v10.6 fix: weekendExportCutoff/weekendCutoffSource used to only be
// computed inside the phase==='A' (weekend) branch below - meaning on
// any weekday, those flow vars were simply never set at all, so the
// "Weekend Export Cutoff" / "Cutoff Source" sensors sat on Unknown
// the entire working week. Compute it every tick instead, unconditio-
// nally, so it's a live preview of tonight's-would-be cutoff even on
// weekdays - the value is only ever actually ACTED on in Phase A,
// this just makes it visible the rest of the week too.
{
    const exportMargin = config.weekendExportMarginPct || 2;
    let exportCutoff = config.weekendExportCutoffFixed || 15.0;
    let cutoffSource = 'fixed';
    if (config.weekendUseSunsetCutoff) {
        const sunsetH = flow.get('sunsetH');
        if (sunsetH !== null && sunsetH !== undefined && sunsetH > 12 && sunsetH < 23) {
            const oW = config.weekendCutoffOffsetWinter || 3.0;
            const oS = config.weekendCutoffOffsetSummer || 1.0;
            const dayOfYr = Math.floor((now - new Date(now.getFullYear(), 0, 0)) / 86400000);
            const seasonPhase = Math.cos((dayOfYr - 172) / 365 * 2 * Math.PI);
            const offset = (oW + oS) / 2 + (oW - oS) / 2 * seasonPhase;
            exportCutoff = sunsetH - offset;
            cutoffSource = 'sunset-' + offset.toFixed(1) + 'h';
        }
    }
    flow.set('weekendExportCutoff', exportCutoff);
    flow.set('weekendCutoffSource', cutoffSource);
}

// -- Phase C: free grid charge (weekdays only by construction) ----
if (phase === 'C') {
    msg.rawIntent = 'FREECHARGE';
    flow.set('requiredSoc', null);
    node.status({ fill: 'green', shape: 'dot', text: 'FREECHARGE - Mon-Fri 21:00-24:00' });
    return msg;
}

// -- SoC missing or stale => protect ------------------------------
const staleMs  = (config.socStaleTimeoutSec || 120) * 1000;
const socAgeMs = flow.get('socLastUpdated') ? (Date.now() - flow.get('socLastUpdated')) : Infinity;
if (soc === null || soc === undefined || socAgeMs > staleMs) {
    msg.rawIntent = 'PROTECT';
    const ageStr = isFinite(socAgeMs) ? Math.round(socAgeMs / 1000) + 's ago' : 'never';
    node.status({ fill: 'red', shape: 'dot', text: 'PROTECT (SoC ' + ageStr + ')' });
    return msg;
}

// -- Overnight hold 00:00 -> overnightEndHour (no solar) ----------
// v16: on surplus days end the hold early enough to reach the floor
// before PV exceeds the inverter ceiling (Forecast Adjuster calc),
// clamped to [overnightEndMinHour, overnightEndHour]
let overnightEndH = config.overnightEndHour || 8;
const earlyStartH = flow.get('earlyExportStartH');
if (flow.get('isSurplusDay') && earlyStartH != null) {
    overnightEndH = Math.min(overnightEndH, Math.max(config.overnightEndMinHour != null ? config.overnightEndMinHour : 8.0, earlyStartH));
}
flow.set('overnightEndH', overnightEndH);

// -- v16.1: big-day pre-dawn export ------------------------------------
// Latches per date once started, so a recomputed (later) start time can't
// switch it off part-way. Exports toward the 40% target, banded relative
// to it in 'ESS Controller', then holds -150W until 08:00.
{
    const todayStr = now.toDateString();
    const tgtSoc   = config.bigDayPreDawnTargetSoc != null ? config.bigDayPreDawnTargetSoc : 40;
    const startH   = flow.get('preDawnExportStartH');
    const bigDay   = flow.get('isBigForecastDay') === true && config.bigDayPreDawnExport !== false;
    if (bigDay && startH != null && nowH >= startH && nowH < overnightEndH) {
        flow.set('preDawnLatchDate', todayStr);
    }
    const latched = bigDay && flow.get('preDawnLatchDate') === todayStr && nowH < overnightEndH;
    flow.set('preDawnExportActive', latched && soc > tgtSoc);
    if (latched) {
        flow.set('daytimeFloor', tgtSoc);
        flow.set('requiredSoc', tgtSoc);
        if (soc > tgtSoc) {
            msg.rawIntent = 'EXPORT';
            flow.set('lastRawIntent', 'EXPORT');
            node.status({ fill: 'blue', shape: 'dot',
                text: 'PRE-DAWN EXPORT | SoC:' + soc.toFixed(1) + '% -> ' + tgtSoc + '% by '
                    + Math.floor(config.bigDayPreDawnTargetHour || 7.5) + ':'
                    + String(Math.round(((config.bigDayPreDawnTargetHour || 7.5) % 1) * 60)).padStart(2, '0') });
        } else {
            msg.rawIntent = 'NORMAL';
            flow.set('lastRawIntent', 'NORMAL');
            node.status({ fill: 'grey', shape: 'dot',
                text: 'PRE-DAWN HOLD | SoC:' + soc.toFixed(1) + '% at target ' + tgtSoc + '% until 08:00' });
        }
        return msg;
    }
}

if (nowH < overnightEndH) {
    msg.rawIntent = 'NORMAL';
    flow.set('requiredSoc', null);
    flow.set('lastRawIntent', 'NORMAL');
    node.status({ fill: 'grey', shape: 'ring',
        text: 'OVERNIGHT HOLD | ' + now.toLocaleTimeString()
            + ' (resumes ' + Math.floor(overnightEndH) + ':' + String(Math.round((overnightEndH % 1) * 60)).padStart(2, '0') + ')' });
    return msg;
}

const effectiveTarget = flow.get('dynamicTarget') || config.targetSocAt2100;
const dynFloorStored  = flow.get('dynamicDaytimeFloor');
// v16: dynamic floor applies on weekends too (Forecast Adjuster returns
// the plain weekend floor when weekendDynamicFloor is off)
const daytimeFloor    = dynFloorStored != null
    ? dynFloorStored
    : (isWeekend ? config.daytimeFloorWeekend : (config.daytimeFloorWeekday || 80));
flow.set('daytimeFloor', daytimeFloor);

// ================= WEEKEND (Phase A) =============================
// No free window - the battery must carry the house through the
// night, so: export surplus in the morning, then charge to 100%
// well before sunset, then trickle out only genuine surplus.
if (phase === 'A') {
    const exportMargin = config.weekendExportMarginPct || 2;
    const exportCutoff = flow.get('weekendExportCutoff');
    const cutoffSource = flow.get('weekendCutoffSource');

    if (nowH < exportCutoff) {
        if (soc < daytimeFloor) {
            msg.rawIntent = 'NORMAL';
            flow.set('requiredSoc', daytimeFloor);
            flow.set('lastRawIntent', 'NORMAL');
            node.status({ fill: 'yellow', shape: 'dot',
                text: 'FLOOR | SoC:' + soc.toFixed(1) + '% floor:' + daytimeFloor + '% (weekend)' });
            return msg;
        }
        if (soc > daytimeFloor + exportMargin) {
            msg.rawIntent = 'EXPORT';
            flow.set('requiredSoc', daytimeFloor);
            flow.set('lastRawIntent', 'EXPORT');
            node.status({ fill: 'blue', shape: 'dot',
                text: 'WEEKEND EXPORT | SoC:' + soc.toFixed(1) + '% floor:' + daytimeFloor
                    + '% cutoff:' + exportCutoff.toFixed(1) + 'h (' + cutoffSource + ')' });
            return msg;
        }
        msg.rawIntent = 'NORMAL';
        flow.set('requiredSoc', daytimeFloor);
        node.status({ fill: 'grey', shape: 'dot',
            text: 'NORMAL | SoC:' + soc.toFixed(1) + '% floor:' + daytimeFloor + '% (weekend)' });
        return msg;
    }

    // After cutoff: charge to full, then export only surplus.
    const fullSoC     = config.weekendFullSoC || 100;
    const exportFloor = config.weekendExportFloorAfterFull || 98;

    if (soc < fullSoC) {
        const kwhNeeded = Math.round((fullSoC - soc) * (config.batteryCapacityKwh || 28.68) / 100 * 10) / 10;
        msg.rawIntent = 'NORMAL';
        flow.set('requiredSoc', fullSoC);
        flow.set('lastRawIntent', 'NORMAL');
        node.status({ fill: 'yellow', shape: 'ring',
            text: 'WEEKEND CHARGE | SoC:' + soc.toFixed(1) + '% -> ' + fullSoC + '%'
                + ' (' + kwhNeeded + 'kWh) cutoff:' + exportCutoff.toFixed(1) + 'h' });
        return msg;
    }
    if (soc >= exportFloor) {
        // v15: park daytimeFloor at the post-cutoff surplus floor so the
        // floor-relative export bands in 'ESS Controller' taper against
        // THIS threshold (98%) rather than the pre-cutoff 85% weekend
        // floor - otherwise a 98-100% surplus trickle was being read as
        // +13 points of headroom and dumped at full -9500W, which drops
        // back under 98% within two ticks and flaps EXPORT <-> RECOVER.
        flow.set('daytimeFloor', exportFloor);
        msg.rawIntent = 'EXPORT';
        flow.set('requiredSoc', exportFloor);
        flow.set('lastRawIntent', 'EXPORT');
        node.status({ fill: 'blue', shape: 'dot',
            text: 'WEEKEND SURPLUS | SoC:' + soc.toFixed(1) + '% >= ' + exportFloor + '%' });
        return msg;
    }
    msg.rawIntent = 'NORMAL';
    flow.set('requiredSoc', exportFloor);
    flow.set('lastRawIntent', 'NORMAL');
    node.status({ fill: 'grey', shape: 'dot',
        text: 'WEEKEND RECOVER | SoC:' + soc.toFixed(1) + '% -> ' + exportFloor + '%' });
    return msg;
}

// ================= WEEKDAY (Phase B) =============================

// -- Evening closed-loop shed: 19:00 -> free window ---------------
if (nowH >= 19 && nowH < freeStartH) {
    const isFirstBlock       = nowH < 20;
    const checkpointSoC      = isFirstBlock ? (config.checkpointSocBy2000 || 65) : effectiveTarget;
    const checkpointDeadline = isFirstBlock ? 20.0 : freeStartH;
    const minutesLeft        = (checkpointDeadline - nowH) * 60;

    if (soc <= checkpointSoC) {
        msg.rawIntent = 'NORMAL';
        flow.set('requiredSoc', checkpointSoC);
        flow.set('dynamicSetpoint', config.minExportSetpoint || -150);
        flow.set('lastRawIntent', 'NORMAL');
        node.status({ fill: 'grey', shape: 'dot',
            text: 'ON TRACK | SoC:' + soc.toFixed(1) + '% <= target:' + checkpointSoC + '%' });
        return msg;
    }

    const battCapKwh = config.batteryCapacityKwh || 28.68;
    const kwhToShed  = (soc - checkpointSoC) / 100 * battCapKwh;
    const liveLoadW  = flow.get('acConsumptionW');
    const houseLoadKw = (liveLoadW !== null && liveLoadW !== undefined
                         ? liveLoadW : (config.averageHouseLoadW || 1400)) / 1000;

    const hoursLeftCk = Math.max(minutesLeft / 60, 1 / 60);
    let dynamicSetpointW = -((kwhToShed / hoursLeftCk) - houseLoadKw) * 1000;
    dynamicSetpointW = Math.max(config.maxExportSetpoint || -9500,
                       Math.min(config.minExportSetpoint || -150, dynamicSetpointW));
    dynamicSetpointW = Math.round(dynamicSetpointW / 100) * 100;

    flow.set('dynamicSetpoint', dynamicSetpointW);
    flow.set('requiredSoc', checkpointSoC);
    flow.set('lastRawIntent', 'DYNAMIC');
    msg.rawIntent       = 'DYNAMIC';
    msg.catchupSetpoint = dynamicSetpointW;
    node.status({ fill: 'blue', shape: 'dot',
        text: 'DYNAMIC | SoC:' + soc.toFixed(1) + '% tgt:' + checkpointSoC + '%'
            + ' SP:' + dynamicSetpointW + 'W load:' + Math.round(houseLoadKw * 1000) + 'W '
            + Math.round(minutesLeft) + 'min left' });
    return msg;
}

// -- Daytime floor -------------------------------------------------
if (soc < daytimeFloor) {
    msg.rawIntent = 'NORMAL';
    flow.set('requiredSoc', daytimeFloor);
    flow.set('lastRawIntent', 'NORMAL');
    node.status({ fill: 'yellow', shape: 'dot',
        text: 'FLOOR | SoC:' + soc.toFixed(1) + '% floor:' + daytimeFloor + '%' });
    return msg;
}

// -- Daytime closed-loop trajectory control ------------------------
// Export whenever remaining export capacity can still land SoC on
// the (forecast-adjusted) 21:00 target.
const battCapKwh   = config.batteryCapacityKwh || 28.68;
const maxExportKw  = Math.abs(config.setpointExport || -9500) / 1000;
const exportablePct = hoursLeft > 0 ? (maxExportKw * hoursLeft / battCapKwh) * 100 : 0;
const requiredSoc  = Math.max(effectiveTarget - exportablePct, daytimeFloor, config.minSocNormal || 20);
flow.set('requiredSoc', requiredSoc);

const margin = config.exportMarginPct || 5;
let rawIntent;
if      (soc > requiredSoc + margin) rawIntent = 'EXPORT';
else if (soc <= requiredSoc)         rawIntent = 'PROTECT';
else                                 rawIntent = flow.get('lastRawIntent') || 'NORMAL';

flow.set('lastRawIntent', rawIntent);
msg.rawIntent     = rawIntent;
msg.requiredSoc   = requiredSoc;
msg.exportablePct = exportablePct;
msg.hoursLeft     = hoursLeft;
node.status({
    fill:  rawIntent === 'EXPORT' ? 'blue' : rawIntent === 'PROTECT' ? 'yellow' : 'grey',
    shape: 'dot',
    text:  rawIntent + ' | SoC:' + soc.toFixed(1) + '% req:' + requiredSoc.toFixed(1)
         + '% tgt:' + effectiveTarget + '%'
});
return msg;

// Final arbiter: any active fault forces FAULT mode (-150W, MinSoC 20).
const socStale       = flow.get('socStale')        || false;
const bmsAllowDis    = flow.get('bmsAllowDischarge');
const bmsBlock       = bmsAllowDis === false;
const manualOverride = flow.get('manualOverride')   || false;
const startupHold    = flow.get('startupHold')      || false;

const anyFault  = socStale || bmsBlock || manualOverride || startupHold;
const finalMode = anyFault ? 'FAULT' : (msg.rawIntent || 'NORMAL');

const state = {
    version:      'v16.1',
    mode:         finalMode,
    rawIntent:    msg.rawIntent || 'NORMAL',
    phase:        flow.get('phase') || 'A',
    isWeekend:    flow.get('isWeekend') || false,
    soc:          flow.get('soc'),
    requiredSoc:  flow.get('requiredSoc'),
    daytimeFloor: flow.get('daytimeFloor'),
    hoursLeft:    flow.get('hoursToFreeWindow'),
    faults: { socStale, bmsBlock, manualOverride, startupHold, anyFault },
    timestamp:    new Date().toISOString()
};
flow.set('currentState', state);
msg.state = state;
msg.mode  = finalMode;

const colour = anyFault ? 'red' :
    finalMode === 'FREECHARGE' ? 'green' :
    (finalMode === 'EXPORT' || finalMode === 'DYNAMIC') ? 'blue' :
    finalMode === 'PROTECT' ? 'yellow' : 'grey';
const active = [
    socStale && 'SoC Stale', bmsBlock && 'BMS Block',
    manualOverride && 'Override', startupHold && 'Startup',
].filter(Boolean);
node.status({ fill: colour, shape: 'dot',
    text: finalMode + (anyFault ? ' | FAULT: ' + active.join(', ') : '') });
return msg;

// Translates mode -> grid setpoint + ESS MinSoC, with:
//   - write deadband (avoid hammering DBus)
//   - periodic re-assertion (recovers from GX reboot / external edits)
//   - immediate write on FAULT
const config   = flow.get('config') || {};
const mode     = msg.mode;
const soc      = flow.get('soc');
const deadband = config.setpointDeadbandW || 300;

let targetSetpoint, targetMinSoc;
let pvOverride = false;

switch (mode) {

    case 'DYNAMIC':
        targetSetpoint = msg.catchupSetpoint || flow.get('dynamicSetpoint') || config.setpointExport || -9500;
        targetMinSoc   = config.minSocNormal || 20;
        break;

    case 'EXPORT': {
        // v15 fix: bands are RELATIVE to the active daytime floor, not
        // absolute SoC. daytimeFloor is dynamic - the Forecast Adjuster
        // can drop it as low as dynamicFloorMinAbs (55) on high-forecast
        // days - but the old rungs were hardcoded at 90/85/82/80, so any
        // time the floor fell below 80 the switch fell straight through
        // to -150W. That silently disabled export in exactly the window
        // the dynamic floor exists to create, which is a large part of
        // why SoC kept walking up to ~97% by midday.
        const floor = flow.get('daytimeFloor') || config.daytimeFloorWeekday || 80;
        const above = soc - floor;              // headroom above the ACTIVE floor

        if      (above >= 10) targetSetpoint = config.exportBandFull    || -9500;
        else if (above >=  5) targetSetpoint = config.exportBandStrong  || -7000;
        else if (above >=  2) targetSetpoint = config.exportBandGentle  || -5000;
        else if (above >=  0) targetSetpoint = config.exportBandMinimal || -2000;
        else                  targetSetpoint = config.setpointNormal    || -150;

        // v15: PV full-export override. Above pvFullExportOnW the array
        // is producing surplus faster than the lower bands can shed it,
        // so throttling just parks the excess in the battery and SoC
        // climbs anyway. Go straight to full export instead.
        // Latching hysteresis (on 8kW / off 7kW) stops the setpoint
        // chattering on a partly-cloudy day when PV hunts the threshold.
        // Scope is deliberately EXPORT-only: below the floor, climbing is
        // the DESIRED behaviour, and forcing full export there would pull
        // the pack down through the floor to feed the grid.
        const pvW     = flow.get('pvPowerW') || 0;
        const pvOn    = config.pvFullExportOnW  || 8000;
        const pvOff   = config.pvFullExportOffW || 7000;
        const latched = flow.get('pvOverrideActive') || false;
        pvOverride    = latched ? (pvW > pvOff) : (pvW > pvOn);
        if (pvOverride) targetSetpoint = config.exportBandFull || -9500;

        targetMinSoc = config.minSocNormal || 20;
        break;
    }

    case 'FREECHARGE':
        targetSetpoint = config.setpointFreeCharge || 9000;
        targetMinSoc   = config.minSocFreeCharge   || 100;
        break;

    default:  // NORMAL, PROTECT, FAULT
        targetSetpoint = config.setpointNormal || -150;
        targetMinSoc   = config.minSocNormal   || 20;
        break;
}

// v16.4: BIG-SOLAR-DAY export. The first time PV exceeds pvFullExportOnW
// (8000W) on a day the forecast calls big (isBigForecastDay), the day is
// latched: export at pvSurplusExportW (-9000W) in EXPORT/NORMAL/PROTECT
// whatever passing cloud does to PV, so the battery is emptied to make room
// for up to ~14.5kW of charging. Stops under pvSurplusExportMinSoc (40%,
// re-arms at ResumeSoc 43%), late in the day (sunset - 3h, else 16:30), or
// when PV stays under pvBigDayLowPvW for pvBigDayLowPvMin minutes (bust day).
let pvSurplusExport = false;
let bigDayArmed = false;
{
    const pvW       = flow.get('pvPowerW') || 0;
    const onW       = config.pvFullExportOnW || 8000;
    const minSoc    = config.pvSurplusExportMinSoc    != null ? config.pvSurplusExportMinSoc    : 40;
    const resumeSoc = config.pvSurplusExportResumeSoc != null ? config.pvSurplusExportResumeSoc : 43;
    const lowW      = config.pvBigDayLowPvW   != null ? config.pvBigDayLowPvW   : 3000;
    const lowMin    = config.pvBigDayLowPvMin != null ? config.pvBigDayLowPvMin : 45;
    const nowB      = new Date();
    const nowHfB    = nowB.getHours() + nowB.getMinutes() / 60;
    const today     = nowB.toDateString();
    const wasActive = flow.get('pvSurplusExportActive') || false;
    const modeOk    = (mode === 'EXPORT' || mode === 'NORMAL' || mode === 'PROTECT');  // never FAULT / FREECHARGE / DYNAMIC
    const bigDay    = flow.get('isBigForecastDay') === true;

    // Arm for the day (re-arm after a bust-day stop if PV recovers)
    if (modeOk && bigDay && pvW > onW &&
        (flow.get('pvBigDayArmedDate') !== today || flow.get('pvBigDayEndedDate') === today)) {
        flow.set('pvBigDayArmedDate', today);
        flow.set('pvBigDayEndedDate', null);
        flow.set('pvBigDayLowSince', null);
    }
    // Bust-day detector: PV low for long enough ends the latch (not a brief cloud)
    if (flow.get('pvBigDayArmedDate') === today && flow.get('pvBigDayEndedDate') !== today) {
        if (pvW < lowW) {
            const since = flow.get('pvBigDayLowSince') || Date.now();
            flow.set('pvBigDayLowSince', since);
            if (Date.now() - since >= lowMin * 60000) flow.set('pvBigDayEndedDate', today);
        } else {
            flow.set('pvBigDayLowSince', null);
        }
    }
    bigDayArmed = flow.get('pvBigDayArmedDate') === today && flow.get('pvBigDayEndedDate') !== today;

    const sunsetH = flow.get('sunsetH');
    const endH    = (sunsetH != null && sunsetH > 12 && sunsetH < 23)
                  ? sunsetH - (config.pvBigDayEndBeforeSunsetH != null ? config.pvBigDayEndBeforeSunsetH : 3)
                  : (config.pvBigDayEndFallbackHour != null ? config.pvBigDayEndFallbackHour : 16.5);
    const socOk   = soc != null && !flow.get('socStale') && (wasActive ? soc >= minSoc : soc >= resumeSoc);

    pvSurplusExport = modeOk && bigDayArmed && nowHfB < endH && socOk;
    if (pvSurplusExport) {
        targetSetpoint = Math.min(targetSetpoint, config.pvSurplusExportW || -9000);
    }
}

// v16.1 hard guard: no export before noExportBeforeHour (default 08:00).
// Clamps any setpoint below setpointNormal back to -150W regardless of
// which branch asked for it. FREECHARGE (positive import) is untouched.
let preDawnClamp = false;
{
    const nowD  = new Date();
    const nowHr = nowD.getHours() + nowD.getMinutes() / 60;
    const limH  = config.noExportBeforeHour != null ? config.noExportBeforeHour : 8;
    const normW = config.setpointNormal || -150;
    const preDawnOk = flow.get('preDawnExportActive') === true;   // big-day pre-dawn export
    if (nowHr < limH && mode !== 'FREECHARGE' && !preDawnOk && targetSetpoint < normW) {
        targetSetpoint = normW;
        pvOverride     = false;
        pvSurplusExport = false;
        preDawnClamp   = true;
    }
}

// Latch clears automatically whenever the mode leaves EXPORT.
flow.set('pvOverrideActive', pvOverride);
flow.set('pvSurplusExportActive', pvSurplusExport);

const lastSetpoint = flow.get('lastSetpoint');
const lastMinSoc   = flow.get('lastMinSoc');
const isFault      = mode === 'FAULT';

// Re-assert periodically so the controller self-heals if anything
// else (GX reboot, VRM, ESS assistant) touches the settings.
const nowTs      = Date.now();
const reassertMs = (config.setpointReassertSec || 300) * 1000;
const lastWrite  = flow.get('lastWriteTs') || 0;
const reassert   = (nowTs - lastWrite) >= reassertMs;

const writeSetpoint = isFault || reassert || lastSetpoint === undefined
                    || Math.abs(targetSetpoint - lastSetpoint) >= deadband;
const writeMinSoc   = isFault || reassert || lastMinSoc !== targetMinSoc;

if (writeSetpoint) flow.set('lastSetpoint', targetSetpoint);
if (writeMinSoc)   flow.set('lastMinSoc',   targetMinSoc);
if (writeSetpoint || writeMinSoc) flow.set('lastWriteTs', nowTs);

let statusText;
if (mode === 'EXPORT') {
    const fl = flow.get('daytimeFloor');
    statusText = 'EXPORT | SoC:' + (soc != null ? soc.toFixed(1) : '?') + '%'
        + (fl != null && soc != null ? ' (+' + (soc - fl).toFixed(1) + ' over ' + fl + '%)' : '')
        + ' SP:' + targetSetpoint + 'W'
        + (pvOverride ? ' | PV-OVR ' + ((flow.get('pvPowerW') || 0) / 1000).toFixed(1) + 'kW' : '');
} else if (mode === 'DYNAMIC') {
    statusText = 'DYNAMIC | SP:' + targetSetpoint + 'W';
} else {
    statusText = mode + ' | SP:' + targetSetpoint + 'W MinSoC:' + targetMinSoc + '%';
}
if (pvSurplusExport) statusText += ' | BIG-DAY EXPORT ' + ((flow.get('pvPowerW') || 0) / 1000).toFixed(1) + 'kW';
else if (bigDayArmed) statusText += ' | BIG-DAY armed (SoC/time hold)';
if (preDawnClamp) statusText += ' | PRE-8AM HOLD';
if (flow.get('preDawnExportActive') === true && mode === 'EXPORT') statusText += ' | PRE-DAWN';
if (reassert && (writeSetpoint || writeMinSoc)) statusText += ' ↻';
node.status({
    fill: mode === 'FAULT' ? 'red' : mode === 'FREECHARGE' ? 'green' :
          (mode === 'EXPORT' || mode === 'DYNAMIC') ? 'blue' : 'grey',
    shape: 'dot', text: statusText
});

return [
    writeSetpoint ? { payload: targetSetpoint } : null,
    writeMinSoc   ? { payload: targetMinSoc   } : null,
];

if (msg.payload !== null && msg.payload !== undefined) {
    node.status({ fill: 'blue', shape: 'dot', text: 'Writing: ' + msg.payload + 'W' });
}
return msg;

if (msg.payload !== null && msg.payload !== undefined) {
    node.status({ fill: 'green', shape: 'dot', text: 'Writing: ' + msg.payload + '%' });
}
return msg;

// Publishes the full controller state every 60s for HA dashboards.
const state = msg.state || flow.get('currentState') || {};
const r2 = v => (v === null || v === undefined) ? null : parseFloat(Number(v).toFixed(2));

state.forecast = {
    kwhToday:      flow.get('forecastKwh'),
    kwhRaw:        flow.get('forecastRaw'),
    dynamicTarget: flow.get('dynamicTarget'),
    arrays:        flow.get('forecastArrays'),
    fetchedAt:     flow.get('forecastFetchedAt'),
    valid:         flow.get('forecastValid') || false,
    confidence:    flow.get('forecastConfidence'),
    surplusKwh:    flow.get('forecastSurplusKwh'),     // v16: PV above inverter ceiling still to come today
    surplusDay:    flow.get('isSurplusDay') || false,  // v16
    trackSoc:      flow.get('surplusTrackSoc'),        // v16: SoC the day is steered onto
    bigDay:        flow.get('isBigForecastDay') || false,  // v16.1: forecast >= bigDayForecastKwh today
    bigDayFloor:   flow.get('bigDayFloorActive') || false, // v16.1: big-day bottom currently applied
    hourly:        flow.get('forecastHourly'),         // v16: [{h, kw}]
};
// v16.1: report what's actually written to the Cerbo, for dashboards
state.setpointW   = flow.get('lastSetpoint');   // grid setpoint (W, negative = export)
state.minSocW     = flow.get('lastMinSoc');     // ESS MinSoC written (%)
state.overnightEndH = flow.get('overnightEndH');
state.weather = flow.get('weather');
state.sun = {
    sunriseH: flow.get('sunriseH'),
    sunsetH:  flow.get('sunsetH'),
    weekendExportCutoff: flow.get('weekendExportCutoff'),
    weekendCutoffSource: flow.get('weekendCutoffSource'),
    overnightEndH: flow.get('overnightEndH'),          // v16
    earlyExportStartH: flow.get('earlyExportStartH'),  // v16
    preDawnExportStartH: flow.get('preDawnExportStartH'),       // v16.1
    preDawnExportActive: flow.get('preDawnExportActive') || false, // v16.1
};
state.battery = {
    cclA: flow.get('battCclA'),          // GSL CCL - graph vs PV to watch MPPT clipping
};
state.pv = {
    powerW:   flow.get('pvPowerW') || 0,
    accumKwh: r2(flow.get('pvAccumKwh') || 0),
    fullExportOverride: (flow.get('pvOverrideActive') || false) || (flow.get('pvSurplusExportActive') || false),   // v15 + v16.3
    surplusExport: flow.get('pvSurplusExportActive') || false,   // v16.4: big-solar-day export active
    bigSolarDayArmed: flow.get('pvBigDayArmedDate') === new Date().toDateString() && flow.get('pvBigDayEndedDate') !== new Date().toDateString(),   // v16.4
};
state.grid = {
    powerW:    flow.get('gridPowerW') || 0,
    exportKwh: r2(flow.get('gridExportKwh') || 0),
    importKwh: r2(flow.get('gridImportKwh') || 0),
};
state.ac = {
    powerW:   flow.get('acConsumptionW') || 0,
    accumKwh: r2(flow.get('acAccumKwh') || 0),
};

msg.topic   = 'victron/ess/state';
msg.payload = JSON.stringify(state);
msg.retain  = false;
msg.qos     = 0;

const wx = state.weather ? state.weather.label : 'no weather';
node.status({ fill: 'blue', shape: 'dot',
    text: 'mode:' + state.mode + ' soc:' + (state.soc != null ? state.soc + '%' : 'n/a')
        + ' pv:' + (state.pv.powerW || 0) + 'W ' + wx
        + (state.pv.fullExportOverride ? ' [PV-OVR]' : '') });
return msg;

// Accumulates kWh imported during Phase C (FREECHARGE) using the
// live measured grid power. Resets at 21:00 on active days.
// Restart-safe: reseeded from the retained energy snapshot.
const state  = msg.state || flow.get('currentState') || {};
const mode   = state.mode;
const now    = new Date();
const config = flow.get('config') || {};
const rate   = config.freeRateNZD || 0.48;   // $/kWh incl. GST

const activeDays  = config.activeDays || [1,2,3,4,5];
const isActiveDay = activeDays.includes(now.getDay());

// v10.9 fix: the old reset only fired during the exact 21:00 hour,
// once per day. If Node-RED restarted/redeployed during that specific
// hour on any given day, the reset for that whole day was silently
// skipped entirely, and the accumulator carried straight over into
// the next night - explaining totals that look like ~2x a normal
// night. Reset on the FIRST Phase C message of a new day instead -
// can't be missed by restart timing, since Phase C only happens
// during the free window anyway.
if (mode === 'FREECHARGE' && flow.get('freeChargeResetDay') !== now.toDateString()) {
    flow.set('freeChargeKwh', 0);
    flow.set('freeChargeResetDay', now.toDateString());
    node.status({ fill: 'yellow', shape: 'dot', text: 'Reset ' + now.toDateString() + ' @ start of Phase C' });
}

if (mode !== 'FREECHARGE') {
    const stored = flow.get('freeChargeKwh') || 0;
    node.status({ fill: 'grey', shape: 'ring',
        text: 'Not Phase C | total: ' + stored.toFixed(3) + ' kWh ($' + (stored * rate).toFixed(2) + ')' });
    return null;
}

const gridPowerW = flow.get('gridPowerW');
if (gridPowerW === null || gridPowerW === undefined) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'Phase C - waiting for grid power' });
    return null;
}

const importW      = Math.max(0, gridPowerW);
const intervalSec  = config.loopIntervalSec || 60;
const updated      = (flow.get('freeChargeKwh') || 0) + (importW * intervalSec) / 3600 / 1000;
flow.set('freeChargeKwh', updated);

const savingsNZD = updated * rate;
node.status({ fill: 'green', shape: 'dot',
    text: 'Phase C: ' + updated.toFixed(3) + ' kWh = $' + savingsNZD.toFixed(2)
        + ' NZD (' + Math.round(importW) + 'W)' });

msg.topic   = 'victron/ess/free_charge_kwh';
msg.payload = JSON.stringify({
    kwhTonight: parseFloat(updated.toFixed(3)),
    powerW:     Math.round(importW),
    savingsNZD: parseFloat(savingsNZD.toFixed(2)),
    rateNZD:    rate,
    activeDay:  isActiveDay,
    timestamp:  now.toISOString()
});
msg.retain = true;
msg.qos    = 1;
return msg;

// v16.5: do NOT publish until the Reseed node has restored today's counters
// (or 30 s have passed with no snapshot). Without this, the first tick after a
// redeploy published zeros as the RETAINED snapshot and wiped the day's totals.
if (!flow.get('energyReseedDone')) {
    const t0 = flow.get('energySnapT0');
    if (!t0) { flow.set('energySnapT0', Date.now()); return null; }
    if (Date.now() - t0 < 30000) return null;
    flow.set('energyReseedDone', true);   // broker/snapshot never arrived: carry on
}
// Retained daily-energy snapshot. Doubles as the restart-persistence
// store: the Reseed node restores these values after a redeploy.
const r3 = v => parseFloat((v || 0).toFixed(3));
msg.topic   = 'victron/ess/energy_today';
msg.payload = JSON.stringify({
    date:               new Date().toDateString(),
    pvKwh:              r3(flow.get('pvAccumKwh')),
    importKwh:          r3(flow.get('gridImportKwh')),
    exportKwh:          r3(flow.get('gridExportKwh')),
    acKwh:              r3(flow.get('acAccumKwh')),
    freeChargeKwh:      r3(flow.get('freeChargeKwh')),
    freeChargeResetDay: flow.get('freeChargeResetDay') || null,
    timestamp:          new Date().toISOString()
});
msg.retain = true;
msg.qos    = 1;
node.status({ fill: 'blue', shape: 'dot',
    text: 'PV:' + r3(flow.get('pvAccumKwh')) + ' ↓' + r3(flow.get('gridImportKwh'))
        + ' ↑' + r3(flow.get('gridExportKwh')) + ' kWh' });
return msg;

// Time-to-empty (to hard min SoC) and time-to-full estimates.
// Charge source detection uses REAL sunrise/sunset from the forecast
// (DST-safe) instead of a fixed window.
const config     = flow.get('config') || {};
const soc        = flow.get('soc');
const acLoadW    = flow.get('acConsumptionW') || 0;
const pvPowerW   = flow.get('pvPowerW') || 0;
const phase      = flow.get('phase');
const battCapKwh = config.batteryCapacityKwh || 28.68;
const minSocHard = config.minSocNormal || 20;
const gridChargeW = config.setpointFreeCharge || 9000;

const now  = new Date();
const nowH = now.getHours() + now.getMinutes() / 60;

// Solar window from live sunrise/sunset (fallbacks only until first fetch)
const sunriseH   = flow.get('sunriseH');
const sunsetH    = flow.get('sunsetH');
const solarStart = (sunriseH !== null && sunriseH !== undefined ? sunriseH : 7.5) + 0.5;
const solarEnd   = (sunsetH  !== null && sunsetH  !== undefined ? sunsetH  : 17.5) - 0.5;

function hhmm(mins) {
    const h = Math.floor(mins / 60), m = Math.floor(mins % 60);
    return h.toString().padStart(2, '0') + ':' + m.toString().padStart(2, '0');
}

// -- Time to empty -------------------------------------------------
let tteMin = null, tteHHMM = null;
if (soc !== null && soc !== undefined && soc > minSocHard && acLoadW > 0) {
    const kwhUsable = ((soc - minSocHard) / 100) * battCapKwh;
    tteMin  = kwhUsable / (acLoadW / 1000) * 60;
    tteHHMM = hhmm(tteMin);
}
flow.set('timeToEmptyMinutes', tteMin);
flow.set('timeToEmptyHHMM', tteHHMM);

// -- Time to full --------------------------------------------------
let ttcMin = null, ttcHHMM = null, chargeSource = '';
if (soc !== null && soc !== undefined && soc < 100) {
    const kwhNeeded = ((100 - soc) / 100) * battCapKwh;
    let chargeW = 0;
    if (phase === 'C') {
        chargeW = gridChargeW;
        chargeSource = 'GRID';
    } else if (nowH >= solarStart && nowH < solarEnd && pvPowerW > 500) {
        chargeW = Math.max(0, (pvPowerW * 0.85) - acLoadW);   // inverter losses approx
        chargeSource = 'SOLAR';
    }
    if (chargeW > 200) {
        ttcMin  = kwhNeeded / (chargeW / 1000) * 60;
        ttcHHMM = hhmm(ttcMin);
    }
}
flow.set('timeToChargeMinutes', ttcMin);
flow.set('timeToChargeHHMM', ttcHHMM);
flow.set('timeToChargeSource', chargeSource);

let text = '';
let fill = 'grey';
if (tteHHMM) {
    text = '↓ ' + tteHHMM + ' to ' + minSocHard + '%';
    fill = tteMin > 240 ? 'green' : tteMin > 120 ? 'yellow' : 'red';
    if (ttcHHMM) { text += ' | ↑ ' + ttcHHMM + ' (' + chargeSource + ')'; if (chargeSource === 'GRID') fill = 'blue'; }
} else if (ttcHHMM) {
    text = '↑ ' + ttcHHMM + ' to 100% (' + chargeSource + ')';
    fill = 'blue';
} else {
    text = 'No load / no charge source';
}
if (soc !== null && soc !== undefined) text += ' | SoC:' + soc.toFixed(1) + '%';
node.status({ fill: fill, shape: 'dot', text: text });
return msg;

const tte = flow.get('timeToEmptyHHMM');
const ttc = flow.get('timeToChargeHHMM');
const soc = flow.get('soc');
msg.topic   = 'victron/ess/battery_time';
msg.payload = JSON.stringify({
    dischargeHHMM: tte || null,
    dischargeMin:  flow.get('timeToEmptyMinutes')  !== null ? Math.round(flow.get('timeToEmptyMinutes'))  : null,
    chargeHHMM:    ttc || null,
    chargeMin:     flow.get('timeToChargeMinutes') !== null ? Math.round(flow.get('timeToChargeMinutes')) : null,
    chargeSource:  flow.get('timeToChargeSource') || '',
    soc:           soc !== null && soc !== undefined ? parseFloat(soc.toFixed(1)) : null,
    timestamp:     new Date().toISOString()
});
msg.retain = true;
msg.qos    = 1;
node.status({ fill: 'blue', shape: 'dot', text: (tte || '--') + ' ↓  ' + (ttc || '--') + ' ↑' });
return msg;

// Trips the socStale fault if SoC hasn't updated within the
// configured timeout (single source of truth: CONFIG).
const config  = flow.get('config') || {};
const timeout = (config.socStaleTimeoutSec || 120) * 1000;
const lastUpd = flow.get('socLastUpdated');
if (!lastUpd || (Date.now() - lastUpd) > timeout) {
    flow.set('socStale', true);
    node.status({ fill: 'red', shape: 'ring', text: 'SoC STALE' });
} else {
    flow.set('socStale', false);
    node.status({ fill: 'green', shape: 'dot', text: 'SoC fresh' });
}
return null;

// Blocks ESS writes for 5s after (re)deploy so all inputs settle.
flow.set('startupHold', true);
node.status({ fill: 'yellow', shape: 'ring', text: 'Startup hold...' });
setTimeout(function() {
    flow.set('startupHold', false);
    node.status({ fill: 'green', shape: 'dot', text: 'Startup complete' });
}, 5000);
return null;

// HA-driven kill switch: forces FAULT mode (-150W hold).
const raw = msg.payload;
let override = false;
if      (typeof raw === 'boolean') override = raw;
else if (typeof raw === 'number')  override = raw === 1;
else if (typeof raw === 'string')  override = ['true','1','on','yes'].includes(raw.toLowerCase());
flow.set('manualOverride', override);
node.status({ fill: override ? 'red' : 'green', shape: 'dot',
    text: override ? 'OVERRIDE ACTIVE' : 'Override off' });
return null;

// Restores today's accumulators from the retained snapshot so a
// Node-RED restart or redeploy never zeroes the daily counters.
// Idempotent: only ever raises a counter, never lowers it.
let p;
try { p = JSON.parse(msg.payload); } catch (e) { return null; }
if (!p || p.date !== new Date().toDateString()) {
    flow.set('energyReseedDone', true);   // v16.5: nothing to restore, publishing may start
    node.status({ fill: 'grey', shape: 'ring', text: 'Snapshot stale - ignored' });
    return null;
}
function restore(key, val) {
    if (val === null || val === undefined || isNaN(val)) return;
    if (val > (flow.get(key) || 0)) flow.set(key, val);
}
restore('gridImportKwh', p.importKwh);
restore('gridExportKwh', p.exportKwh);
restore('acAccumKwh',    p.acKwh);
restore('freeChargeKwh', p.freeChargeKwh);
if (p.freeChargeResetDay) flow.set('freeChargeResetDay', p.freeChargeResetDay);
flow.set('gridEnergyDay', p.date);
flow.set('energyReseedDone', true);   // v16.5: restored, publishing may start
flow.set('acAccumDay',    p.date);
node.status({ fill: 'green', shape: 'dot',
    text: 'Restored ↓' + (p.importKwh || 0) + ' ↑' + (p.exportKwh || 0)
        + ' free:' + (p.freeChargeKwh || 0) + ' kWh' });
return null;

if (msg.payload === null || msg.payload === undefined || isNaN(msg.payload)) {
    flow.set('soc', null);
    flow.set('socStale', true);
    node.status({ fill: 'red', shape: 'dot', text: 'SoC missing' });
    return null;
}
const soc = parseFloat(msg.payload);
flow.set('soc', soc);
flow.set('socLastUpdated', Date.now());
flow.set('socStale', false);
node.status({ fill: 'green', shape: 'dot', text: 'SoC: ' + soc.toFixed(1) + '%' });
return null;

// GSL battery manages charge AND discharge through CCL.
// CCL taper near full is normal behaviour (and clips the MPPTs -
// cclA is stored + published so it can be graphed against PV in HA).
// CCL=0 at high SoC = full battery, NOT a fault.
// CCL=0 at low SoC  = genuine BMS block -> FAULT.
const ccl = parseFloat(msg.payload);
if (isNaN(ccl)) {
    node.status({ fill: 'grey', shape: 'ring', text: 'Waiting for BMS data' });
    return null;
}
flow.set('battCclA', ccl);
const soc = flow.get('soc');

if (ccl === 0 && soc !== null && soc !== undefined && soc >= 95) {
    flow.set('bmsAllowDischarge', true);
    node.status({ fill: 'green', shape: 'dot',
        text: 'CCL:0A - full battery (' + soc.toFixed(1) + '%) OK' });
    return null;
}
const blocked = ccl === 0;
flow.set('bmsAllowDischarge', !blocked);
node.status(blocked
    ? { fill: 'red', shape: 'dot', text: 'BMS BLOCK - CCL:0A SoC:' + (soc != null ? soc.toFixed(1) : '?') + '%' }
    : { fill: 'green', shape: 'dot', text: 'CCL: ' + ccl + 'A' });
return null;

// Live grid power (+import / -export) AND software energy meter.
// Integrates with REAL time deltas (the vebus kWh counters are not
// available on this system). Daily reset at midnight; restart-safe
// via the retained energy snapshot reseed.
const w = parseFloat(msg.payload);
if (isNaN(w)) {
    node.status({ fill: 'grey', shape: 'ring', text: 'No grid data' });
    return null;
}
flow.set('gridPowerW', w);

const now   = Date.now();
const today = new Date().toDateString();
if (flow.get('gridEnergyDay') !== today) {
    flow.set('gridImportKwh', 0);
    flow.set('gridExportKwh', 0);
    flow.set('gridEnergyDay', today);
}
const lastTs = flow.get('gridLastTs');
let dtSec = lastTs ? (now - lastTs) / 1000 : 0;
if (dtSec < 0 || dtSec > 120) dtSec = 0;   // ignore gaps (restart / reconnect)
flow.set('gridLastTs', now);

const kwh = Math.abs(w) * dtSec / 3600 / 1000;
if (w > 0) flow.set('gridImportKwh', (flow.get('gridImportKwh') || 0) + kwh);
else       flow.set('gridExportKwh', (flow.get('gridExportKwh') || 0) + kwh);

node.status({
    fill: w > 0 ? 'red' : 'green', shape: 'dot',
    text: (w > 0 ? 'Import: ' : 'Export: ') + Math.abs(Math.round(w)) + 'W'
        + ' | ↑' + (flow.get('gridExportKwh') || 0).toFixed(2)
        + ' ↓' + (flow.get('gridImportKwh') || 0).toFixed(2) + ' kWh'
});

// v10.5: expose the daily accumulator TOTALS this node already
// maintains (gridImportKwh / gridExportKwh), not another live/instant
// value - VRM's own "To Grid" / "From Grid" widgets show this same
// kind of running total, this just makes it visible inside Node-RED too.
return [
    { payload: +(flow.get('gridImportKwh') || 0).toFixed(3), topic: 'grid_import_kwh_today' },
    { payload: +(flow.get('gridExportKwh') || 0).toFixed(3), topic: 'grid_export_kwh_today' }
];

// Live house load (used by the evening dynamic setpoint) plus a
// daily kWh accumulator using REAL time deltas (v10 fix: the old
// version assumed a fixed 5 s message interval and drifted).
const raw = parseFloat(msg.payload);
if (isNaN(raw)) {
    node.status({ fill: 'grey', shape: 'ring', text: 'No data - using fallback' });
    return null;
}
const w = Math.abs(raw);
flow.set('acConsumptionW', w);

const now   = Date.now();
const today = new Date().toDateString();
if (flow.get('acAccumDay') !== today) {
    flow.set('acAccumKwh', 0);
    flow.set('acAccumDay', today);
}
const lastTs = flow.get('acLastTs');
let dtSec = lastTs ? (now - lastTs) / 1000 : 0;
if (dtSec < 0 || dtSec > 120) dtSec = 0;
flow.set('acLastTs', now);

let accum = (flow.get('acAccumKwh') || 0) + (w * dtSec) / 3600 / 1000;

// Sanity clamp (v10.1 fix): a house does not consume 100+ kWh/day.
// Catches any accumulator that ran away because a day-rollover was missed.
if (accum > 100) {
    node.warn('acAccumKwh implausible (' + accum.toFixed(1) + ' kWh) - forcing reset');
    accum = 0;
}
flow.set('acAccumKwh', accum);
node.status({ fill: 'green', shape: 'dot',
    text: 'Load: ' + Math.round(w) + 'W | today: ' + accum.toFixed(2) + ' kWh' });
return null;

// Receives tagged power messages from all 5 MPPTs (msg.slot 1-5).
const w = parseFloat(msg.payload) || 0;
const s = msg.slot;
const arr = flow.get('pvMpptW') || [0, 0, 0, 0, 0];
if (s >= 1 && s <= 5) arr[s - 1] = w;
flow.set('pvMpptW', arr);
const total = Math.round(arr.reduce((a, b) => a + b, 0));
flow.set('pvPowerW', total);
node.status({ fill: 'yellow', shape: 'dot',
    text: 'Total: ' + total + 'W | ' + arr.map((v, i) => 'M' + (i + 1) + ':' + Math.round(v)).join(' ') });
return null;

// Receives tagged daily-yield messages from all 5 MPPTs (msg.slot 1-5).
// v10.1 fix: hold last-known-good value on a bad/unavailable reading
// instead of zeroing that MPPT's contribution (VE.Direct comms blips
// were silently wiping the whole daily total).
const raw = parseFloat(msg.payload);
const s = msg.slot;
const arr = flow.get('pvMpptYield') || [0, 0, 0, 0, 0];
if (s >= 1 && s <= 5) {
    if (!isNaN(raw)) {
        arr[s - 1] = raw;
    } else {
        node.warn('MPPT slot ' + s + ' unavailable - holding last value (' + (arr[s - 1] || 0).toFixed(2) + ' kWh)');
    }
}
flow.set('pvMpptYield', arr);
const total = parseFloat(arr.reduce((a, b) => a + b, 0).toFixed(3));
flow.set('pvAccumKwh', total);
node.status({ fill: 'yellow', shape: 'dot',
    text: 'Total: ' + total.toFixed(2) + ' kWh | ' + arr.map((v, i) => 'M' + (i + 1) + ':' + v.toFixed(1)).join(' ') });
return null;

// v10.4: was suppressing fetches outside 06:00-21:00 to save API
// calls, but that meant forecast data was stale/missing overnight -
// now runs 24/7 so the dashboard always has current forecast data.
node.status({ fill: 'green', shape: 'dot', text: 'Passed ' + new Date().toLocaleTimeString() });
return msg;

// Free, key-less API. timezone=Pacific/Auckland means all returned
// times (incl. sunrise/sunset) are NZ LOCAL and track DST as long as
// the Cerbo clock is on Pacific/Auckland - no manual offset needed.
const config = flow.get('config') || {};
const lat = config.latitude  || -37.2540109;
const lon = config.longitude || 175.0050308;
msg.url = 'https://api.open-meteo.com/v1/forecast'
    + '?latitude=' + lat
    + '&longitude=' + lon
    + '&hourly=direct_radiation,diffuse_radiation,direct_normal_irradiance'
    + ',cloudcover,precipitation_probability,weathercode'
    + '&daily=weathercode,precipitation_sum,precipitation_probability_max,sunrise,sunset'
    + '&timezone=Pacific%2FAuckland'
    + '&forecast_days=1';
msg.method = 'GET';
node.status({ fill: 'blue', shape: 'ring', text: 'Fetching forecast + sun...' });
return msg;

// Per-array plane-of-array (POA) forecast for the remaining day,
// weather condition, sunrise/sunset, and a live confidence ratio
// (actual PV so far vs what the model predicted for the morning).
try {
    const data   = JSON.parse(msg.payload);
    const hourly = data.hourly;
    const daily  = data.daily;
    if (!hourly || !hourly.time) throw new Error('Invalid Open-Meteo response');

    const config = flow.get('config') || {};
    const now    = new Date();
    const nowH   = now.getHours() + now.getMinutes() / 60;
    const endH   = config.freeWindowStartHour || 21;

    const weatherCode = daily && daily.weathercode ? daily.weathercode[0] : 0;
    const precipSum   = daily && daily.precipitation_sum ? daily.precipitation_sum[0] : 0;
    const precipProb  = daily && daily.precipitation_probability_max ? daily.precipitation_probability_max[0] : 0;

    // Sunrise/sunset arrive as NZ-local ISO strings (DST already
    // applied by the API); Date() parses them in the Cerbo's local
    // zone, which must also be Pacific/Auckland.
    function timeToDecimal(iso) {
        if (!iso) return null;
        const d = new Date(iso);
        return d.getHours() + d.getMinutes() / 60 + d.getSeconds() / 3600;
    }
    const sunriseH = timeToDecimal(daily && daily.sunrise ? daily.sunrise[0] : null);
    const sunsetH  = timeToDecimal(daily && daily.sunset  ? daily.sunset[0]  : null);
    flow.set('sunriseH', sunriseH);
    flow.set('sunsetH',  sunsetH);

    function weatherDescription(code) {
        if (code === 0)  return { label: 'Clear sky',     icon: 'sunny',   confidence: 1.0 };
        if (code <= 3)   return { label: 'Partly cloudy', icon: 'cloudy',  confidence: 0.85 };
        if (code <= 48)  return { label: 'Foggy',         icon: 'foggy',   confidence: 0.6 };
        if (code <= 67)  return { label: 'Rainy',         icon: 'rainy',   confidence: 0.4 };
        if (code <= 77)  return { label: 'Snowy',         icon: 'snowy',   confidence: 0.3 };
        if (code <= 82)  return { label: 'Showers',       icon: 'showers', confidence: 0.5 };
        if (code <= 99)  return { label: 'Thunderstorm',  icon: 'storm',   confidence: 0.2 };
        return                  { label: 'Unknown',       icon: 'unknown', confidence: 0.7 };
    }
    const weather = weatherDescription(weatherCode);

    // Average cloud cover for the remaining daylight hours
    let cloudSum = 0, cloudCount = 0;
    (hourly.cloudcover || []).forEach((cc, i) => {
        const t  = new Date(hourly.time[i]);
        const tH = t.getHours() + t.getMinutes() / 60;
        if (t.toDateString() !== now.toDateString()) return;
        if (tH < nowH || tH >= endH) return;
        cloudSum += (cc || 0);
        cloudCount++;
    });
    const avgCloudPct = cloudCount ? Math.round(cloudSum / cloudCount) : 0;

    // -- POA transposition per array (geometry from CONFIG) -------
    const arrays = config.solarArrays || [
        { name: 'ENE',    azimuth:  57, tilt: 23, capacityKw: 6.09 },
        { name: 'NNW/NW', azimuth: 326, tilt: 23, capacityKw: 7.83 },
        { name: 'WSW',    azimuth: 237, tilt: 23, capacityKw: 5.52 },
    ];
    const systemEfficiency = config.systemEfficiency || 0.82;
    const latRad = (config.latitude || -37.254) * Math.PI / 180;

    function toRad(d) { return d * Math.PI / 180; }
    const dayOfYear = Math.floor((now - new Date(now.getFullYear(), 0, 0)) / 86400000);
    const decl = toRad(23.45 * Math.sin(toRad(360 / 365 * (dayOfYear - 81))));

    function sinElev(h) {
        const ha = toRad((h - 12) * 15);
        return Math.sin(latRad) * Math.sin(decl) + Math.cos(latRad) * Math.cos(decl) * Math.cos(ha);
    }
    function solAz(h) {
        const se = sinElev(h);
        if (se <= 0) return 0;
        const cosAz = (Math.sin(decl) - se * Math.sin(latRad)) / (Math.sqrt(1 - se * se) * Math.cos(latRad));
        let az = Math.acos(Math.max(-1, Math.min(1, cosAz)));
        if (h > 12) az = 2 * Math.PI - az;
        return az;
    }
    function tiltFactor(h, azDeg, tiltDeg) {
        const se = sinElev(h);
        if (se <= 0) return 0;
        const cosAOI = se * Math.cos(toRad(tiltDeg))
            + Math.sqrt(1 - se * se) * Math.sin(toRad(tiltDeg)) * Math.cos(solAz(h) - toRad(azDeg));
        return Math.max(0, cosAOI);
    }
    function poaKwh(arr, fromH, toH) {
        let sum = 0;
        hourly.time.forEach((timeStr, i) => {
            const t  = new Date(timeStr);
            const tH = t.getHours() + t.getMinutes() / 60;
            if (t.toDateString() !== now.toDateString()) return;
            // v16 fix: weight by the part of this hour inside [fromH, toH).
            // v15 counted the in-progress hour as fully "morning" and not at
            // all "remaining", so confidence (actual/modelled) dipped after
            // every refresh past :00 and the remaining forecast was short.
            const overlap = Math.min(tH + 1, toH) - Math.max(tH, fromH);
            if (overlap <= 0) return;
            const ghi     = Math.max(0, hourly.direct_radiation[i] || 0);
            const diffuse = Math.max(0, hourly.diffuse_radiation[i] || 0);
            const dni     = Math.max(0, hourly.direct_normal_irradiance[i] || 0);
            const tf      = tiltFactor(tH + 0.5, arr.azimuth, arr.tilt);
            const poa     = dni * tf + diffuse * (1 + Math.cos(toRad(arr.tilt))) / 2
                          + ghi * 0.2 * (1 - Math.cos(toRad(arr.tilt))) / 2;
            sum += (poa / 1000) * arr.capacityKw * systemEfficiency * overlap;
        });
        return sum;
    }

    let totalKwh = 0, morningForecast = 0;
    const arrayResults = [];
    arrays.forEach(arr => {
        const remaining = poaKwh(arr, nowH, endH);
        arrayResults.push({ name: arr.name, kwh: parseFloat(remaining.toFixed(2)) });
        totalKwh        += remaining;
        morningForecast += poaKwh(arr, 6, nowH);
    });
    totalKwh = parseFloat(totalKwh.toFixed(2));

    // v16: hourly whole-array PV profile for today (average kW per hour,
    // raw - confidence is applied in the Forecast Adjuster). Same POA
    // model as poaKwh() above, one hour at a time.
    const hourlyPv = [];
    hourly.time.forEach((timeStr, i) => {
        const t = new Date(timeStr);
        if (t.toDateString() !== now.toDateString()) return;
        const tH      = t.getHours();
        const ghi     = Math.max(0, hourly.direct_radiation[i] || 0);
        const diffuse = Math.max(0, hourly.diffuse_radiation[i] || 0);
        const dni     = Math.max(0, hourly.direct_normal_irradiance[i] || 0);
        let kw = 0;
        arrays.forEach(arr => {
            const tf  = tiltFactor(tH + 0.5, arr.azimuth, arr.tilt);
            const poa = dni * tf + diffuse * (1 + Math.cos(toRad(arr.tilt))) / 2
                      + ghi * 0.2 * (1 - Math.cos(toRad(arr.tilt))) / 2;
            kw += (poa / 1000) * arr.capacityKw * systemEfficiency;
        });
        hourlyPv.push({ h: tH, kw: parseFloat(kw.toFixed(2)) });
    });
    flow.set('forecastHourly', hourlyPv);

    // -- Confidence: actual PV so far vs modelled morning ---------
    const pvAccumKwh = flow.get('pvAccumKwh') || 0;
    let confidenceRatio = 1.0;
    let confidenceLabel = 'Insufficient data';
    if (nowH >= 9 && morningForecast > 0.5) {
        confidenceRatio = Math.min(1.5, pvAccumKwh / morningForecast);
        if      (confidenceRatio >= 0.9) confidenceLabel = 'On track';
        else if (confidenceRatio >= 0.7) confidenceLabel = 'Slightly below forecast';
        else if (confidenceRatio >= 0.5) confidenceLabel = 'Well below forecast';
        else                             confidenceLabel = 'Far below - likely overcast';
    }
    const adjustedForecastKwh = nowH >= 9
        ? parseFloat((totalKwh * Math.min(1.0, confidenceRatio)).toFixed(2))
        : totalKwh;

    flow.set('forecastKwh', adjustedForecastKwh);
    flow.set('forecastRaw', totalKwh);
    flow.set('forecastArrays', arrayResults);
    flow.set('forecastFetchedAt', now.toISOString());
    flow.set('forecastValid', true);
    flow.set('weather', {
        code: weatherCode, label: weather.label, icon: weather.icon,
        cloudPct: avgCloudPct, precipProb: precipProb, precipSumMm: precipSum,
        confidence: weather.confidence, sunriseH: sunriseH, sunsetH: sunsetH,
    });
    flow.set('forecastConfidence', {
        ratio: parseFloat(confidenceRatio.toFixed(2)),
        label: confidenceLabel,
        actualKwh: parseFloat(pvAccumKwh.toFixed(2)),
        predictedKwh: parseFloat(morningForecast.toFixed(2)),
        adjustedKwh: adjustedForecastKwh,
    });

    function hhmm(h) {
        if (h === null || h === undefined) return '?';
        return Math.floor(h) + ':' + String(Math.round((h % 1) * 60)).padStart(2, '0');
    }
    node.status({ fill: 'green', shape: 'dot',
        text: weather.label + ' ' + avgCloudPct + '% cloud | '
            + adjustedForecastKwh.toFixed(1) + 'kWh | rise:' + hhmm(sunriseH) + ' set:' + hhmm(sunsetH) });

    msg.forecastKwh    = adjustedForecastKwh;
    msg.forecastArrays = arrayResults;
    return msg;

} catch (e) {
    flow.set('forecastValid', false);
    node.status({ fill: 'red', shape: 'dot', text: 'Forecast error: ' + e.message });
    return null;
}

const sunriseH  = flow.get('sunriseH');
const sunsetH   = flow.get('sunsetH');
const cutoff    = flow.get('weekendExportCutoff');
const cutoffSrc = flow.get('weekendCutoffSource') || 'unknown';
function decimalToHHMM(h) {
    if (h === null || h === undefined) return null;
    const hh = Math.floor(h), mm = Math.round((h - hh) * 60);
    return hh.toString().padStart(2, '0') + ':' + mm.toString().padStart(2, '0');
}
msg.topic   = 'victron/ess/sun';
msg.payload = JSON.stringify({
    sunriseHHMM:         decimalToHHMM(sunriseH),
    sunsetHHMM:          decimalToHHMM(sunsetH),
    sunriseDecimal:      sunriseH != null ? parseFloat(sunriseH.toFixed(3)) : null,
    sunsetDecimal:       sunsetH  != null ? parseFloat(sunsetH.toFixed(3))  : null,
    weekendCutoffHHMM:   decimalToHHMM(cutoff),
    weekendCutoffSource: cutoffSrc,
    timestamp:           new Date().toISOString()
});
msg.retain = true;
msg.qos    = 1;
node.status({ fill: 'yellow', shape: 'dot',
    text: 'rise:' + (decimalToHHMM(sunriseH) || '?') + ' set:' + (decimalToHHMM(sunsetH) || '?')
        + ' cutoff:' + (decimalToHHMM(cutoff) || '?') + ' (' + cutoffSrc + ')' });
return msg;

// Mark forecast invalid so the controller falls back to the base
// 21:00 target rather than acting on stale numbers.
flow.set('forecastValid', false);
const errMsg = msg.error ? msg.error.message : 'Unknown error';
node.error('Forecast error: ' + errMsg);
node.status({ fill: 'red', shape: 'dot', text: 'Error: ' + errMsg.substring(0, 40) });
return null;

// Independent day-rollover safety net (v10.1 addition).
// Runs every 60s off the Tick timer -- NOT dependent on grid/AC/PV
// messages actually arriving -- so a dead sensor feed spanning
// midnight can never leave an accumulator un-reset.
const todayStr = new Date().toDateString();

if (flow.get('gridEnergyDay') !== todayStr) {
    flow.set('gridImportKwh', 0);
    flow.set('gridExportKwh', 0);
    flow.set('gridEnergyDay', todayStr);
    node.warn('Forced grid accumulator reset (day-rollover watchdog)');
}
if (flow.get('acAccumDay') !== todayStr) {
    flow.set('acAccumKwh', 0);
    flow.set('acAccumDay', todayStr);
    node.warn('Forced AC accumulator reset (day-rollover watchdog)');
}
if (flow.get('pvAccumDay') !== todayStr) {
    flow.set('pvMpptYield', [0, 0, 0, 0, 0]);
    flow.set('pvAccumKwh', 0);
    flow.set('pvAccumDay', todayStr);
    node.warn('Forced PV accumulator reset (day-rollover watchdog)');
}
// v10.9 safety net: catches the case where Phase C never engages at
// all on a given night (e.g. a fault, or manual override staying on
// through the free window) - the primary reset in the Free-charge
// accumulator node only fires on the first Phase C message, so if
// that never happens, this is the only thing that clears yesterday's
// total before a new day starts.
if (flow.get('freeChargeResetDay') !== todayStr) {
    flow.set('freeChargeKwh', 0);
    flow.set('freeChargeResetDay', todayStr);
    node.warn('Forced free-charge accumulator reset (day-rollover watchdog)');
}

// Belt-and-braces sanity clamp, independent of the one in the AC node.
if ((flow.get('acAccumKwh') || 0) > 100) {
    node.warn('acAccumKwh implausible (' + flow.get('acAccumKwh').toFixed(1) + ' kWh) - forcing reset');
    flow.set('acAccumKwh', 0);
}

node.status({ fill: 'grey', shape: 'dot', text: 'watch: ' + todayStr });
return null;

// v10.8: PV / battery / grid routing breakdown - live replacement for
// the third-party VRM integration's known-unreliable battery-flow
// figures. NOT a direct hardware measurement (Victron doesn't expose
// this exact breakdown on the wire) - reconstructed from four live
// power readings using the same priority-order logic real Victron ESS
// systems use internally:
//   1. PV serves the load first
//   2. Leftover PV charges the battery
//   3. Leftover PV after that exports to grid
//   4. If PV can't cover the load, battery discharges to cover it
//   5. If battery can't cover it either, grid imports the rest
//   6. If battery is discharging MORE than the load needs, the extra
//      exports to grid (rare, e.g. deliberate battery-export mode)
//
// IMPORTANT: verify /Dc/0/Power's sign convention on your system before
// trusting this - this assumes POSITIVE = charging, NEGATIVE =
// discharging (Victron's usual convention). If the numbers come out
// backwards (e.g. "Battery to Consumers" only shows values while your
// battery SoC is climbing), the sign is flipped - negate battPowerW
// at the top of this function.

const w = parseFloat(msg.payload);
if (isNaN(w)) { node.status({fill:'grey',shape:'ring',text:'No battery power data'}); return null; }
flow.set('battPowerW', w);

const pvW    = flow.get('pvPowerW') || 0;
const gridW  = flow.get('gridPowerW') || 0;       // +import / -export
const loadW  = flow.get('acConsumptionW') || 0;
const battW  = w;                                  // +charge / -discharge (verify!)

// Step 1-3: PV allocation
const pvToConsumersW = Math.min(pvW, Math.max(loadW, 0));
let remainingPvW      = Math.max(pvW - pvToConsumersW, 0);
let remainingLoadW    = Math.max(loadW - pvToConsumersW, 0);

const pvToBatteryW = battW > 0 ? Math.min(remainingPvW, battW) : 0;
remainingPvW -= pvToBatteryW;
// whatever PV is left after load+battery would be exporting - but we
// use the REAL metered grid export for that figure instead (more
// accurate than this reconstruction), computed further down.

// Step 4-6: battery covering load, and any surplus battery export
const battToConsumersW = battW < 0 ? Math.min(remainingLoadW, -battW) : 0;
remainingLoadW -= battToConsumersW;
const battSurplusW = battW < 0 ? Math.max(-battW - battToConsumersW, 0) : 0;

// Total metered export (from the existing, hardware-accurate grid
// integrator) = pvToGrid + battToGrid combined. Attribute the surplus
// battery discharge (if any) to battToGrid, and give PV the remainder -
// this keeps the headline export number tied to the real meter instead
// of this reconstruction.
const totalExportW = gridW < 0 ? -gridW : 0;
const battToGridW  = Math.min(battSurplusW, totalExportW);
const pvToGridW     = Math.max(totalExportW - battToGridW, 0);

flow.set('routing_pvToConsumersW', pvToConsumersW);
flow.set('routing_pvToBatteryW', pvToBatteryW);
flow.set('routing_pvToGridW', pvToGridW);
flow.set('routing_battToConsumersW', battToConsumersW);
flow.set('routing_battToGridW', battToGridW);

// ── Daily kWh accumulation (day-rollover-safe, mirrors the watchdog) ──
const now = Date.now();
const today = new Date().toDateString();
if (flow.get('routingDay') !== today) {
    flow.set('routing_pvToConsumersKwh', 0);
    flow.set('routing_pvToBatteryKwh', 0);
    flow.set('routing_pvToGridKwh', 0);
    flow.set('routing_battToConsumersKwh', 0);
    flow.set('routing_battToGridKwh', 0);
    flow.set('routingDay', today);
}
const lastTs = flow.get('routingLastTs');
let dtSec = lastTs ? (now - lastTs) / 1000 : 0;
if (dtSec < 0 || dtSec > 120) dtSec = 0;
flow.set('routingLastTs', now);

const toKwh = (pw) => (pw * dtSec) / 3600 / 1000;
flow.set('routing_pvToConsumersKwh', (flow.get('routing_pvToConsumersKwh') || 0) + toKwh(pvToConsumersW));
flow.set('routing_pvToBatteryKwh', (flow.get('routing_pvToBatteryKwh') || 0) + toKwh(pvToBatteryW));
flow.set('routing_pvToGridKwh', (flow.get('routing_pvToGridKwh') || 0) + toKwh(pvToGridW));
flow.set('routing_battToConsumersKwh', (flow.get('routing_battToConsumersKwh') || 0) + toKwh(battToConsumersW));
flow.set('routing_battToGridKwh', (flow.get('routing_battToGridKwh') || 0) + toKwh(battToGridW));

node.status({fill:'yellow', shape:'dot',
    text: 'PV\u2192C:' + Math.round(pvToConsumersW) + 'W PV\u2192B:' + Math.round(pvToBatteryW)
        + 'W B\u2192C:' + Math.round(battToConsumersW) + 'W'});
return null;

// Publishes the routing breakdown every 60s alongside the main state.
msg.topic = 'victron/ess/routing';
msg.payload = JSON.stringify({
    pvToConsumersKwh:   +(flow.get('routing_pvToConsumersKwh') || 0).toFixed(2),
    pvToBatteryKwh:     +(flow.get('routing_pvToBatteryKwh') || 0).toFixed(2),
    pvToGridKwh:        +(flow.get('routing_pvToGridKwh') || 0).toFixed(2),
    battToConsumersKwh: +(flow.get('routing_battToConsumersKwh') || 0).toFixed(2),
    battToGridKwh:      +(flow.get('routing_battToGridKwh') || 0).toFixed(2),
});
msg.retain = false;
msg.qos = 0;
node.status({fill:'blue', shape:'dot', text:'published'});
return msg;
